-- =====================================================================
-- File   : 04_regional_partner_seed.sql   (Abrar)
-- Purpose: Realistic sample data for regional_partner.
-- PLANTED DATA-QUALITY ISSUES (for Member 2's ETL cleansing):
--   * TRV-0001..TRV-0010 are the SAME people as mainline passengers
--     1,2,3,6,9,14,17,21,23,30 (match on lower(email); name casing differs)
--   * TRV-0031 duplicates TRV-0011, TRV-0032 duplicates TRV-0016 (UPPER-case copy)
--   * birth_date_text in 4 formats: DD/MM/YYYY, YYYY-MM-DD, 'Mon DD YYYY', MM-DD-YYYY
--   * country free text: 'Bahrain','bahrain','BAHRAIN','Kingdom of Bahrain','KSA','UK',NULL
--   * city names with mixed casing / aliases ('Manama','MANAMA','Bahrain','Kuwait')
--   * travel_class: 'Economy','ECONOMY','econ','Y','Business','Prem Econ',NULL ...
--   * reservation_status casing: 'Confirmed','confirmed','CANCELLED','cxl','Flown'
--   * fare_line currency 'BHD' / 'bhd' / 'USD'; some fares drift from route.fare_amount
--   * fare_line 17 and 44 have NULL fare_amount; last 3 fare_line rows are exact duplicates
-- =====================================================================
SET search_path TO regional_partner, public;





-- Move identity sequences past the explicit IDs used above
SELECT setval(pg_get_serial_sequence('regional_partner.route','route_id'),         (SELECT max(route_id)     FROM route));
SELECT setval(pg_get_serial_sequence('regional_partner.fare_line','fare_line_id'), (SELECT max(fare_line_id) FROM fare_line));